  form.addEventListener("submit",async event=>{event.preventDefault();start.disabled=true;input.disabled=true;verificationMode.disabled=true;spinner.hidden=false;startLabel.textContent="Beweise werden erstellt";result.hidden=true;protection.hidden=true;events.replaceChildren();trace.hidden=false;trace.open=true;const state=document.getElementById("run-state");state.textContent="Verbindung wird aufgebaut …";state.className="run-state";try{const run=await streamEvidenceRun({url:input.value,verification_mode:verificationMode.checked});if(!run)throw new Error("Der Prüfverlauf wurde unerwartet beendet.");if(run.case_detail)renderArtifacts(run.case_detail);else if(run.result_available)await loadNewest(run.url)}catch(error){state.textContent=error.message;state.title=error.message;state.className="run-state warn"}finally{start.disabled=false;input.disabled=false;verificationMode.disabled=false;spinner.hidden=true;startLabel.textContent="Erfassung starten"}});
