    .event:not(:last-child)::before { content:""; position:absolute; left:4px; top:15px; bottom:-2px; width:1px; background:#c9ddd1; }
    .event-dot { position:relative; z-index:1; width:9px; height:9px; margin-top:5px; border:2px solid #85aa98; border-radius:50%; background:#f3f8f5; }
    .event.done .event-dot { border-color:#4b8a70; background:#4b8a70; }
    .event.active .event-dot { border-color:#3e8066; background:#dceee5; box-shadow:0 0 0 4px rgb(62 128 102 / .12); animation:pulse 1.5s ease-in-out infinite; }
    .event.failed .event-dot,.event.warning .event-dot { border-color:#b97724; background:#f8dfbd; }
    @keyframes pulse { 50% { box-shadow:0 0 0 7px rgb(62 128 102 / 0); } }
