<body>
  <header><div class="head"><img class="logo" src="/static/muclegal-logo-light.png" alt="MucLegal"><span class="brand-rule"></span><span class="brand-name">BeweisLab</span><div class="verification-control"><label class="verification-switch" for="verification-mode"><input id="verification-mode" type="checkbox" checked><span class="switch-track" aria-hidden="true"></span><span class="verification-label">Automatische Überprüfung</span></label><button class="info" type="button" data-info="Standardmäßig beginnt das BeweisLab mit dem direkten öffentlichen Abruf. Erst wenn dabei ein tatsächlicher Seitenschutz oder eine reine JavaScript-Hülle erkannt wird, schaltet es automatisch in den Überprüfungsmodus und lädt die Seite einmalig in einem echten Browser. Vor Screenshots darf es ausschließlich sichtbare, eindeutig datensparsame Cookie-Optionen wie „Alle ablehnen“ oder „Nur notwendige“ wählen. CAPTCHAs, Logins und andere Seitenelemente werden nicht bedient; keine Tarntechniken werden verwendet. Schalte diese Automatik aus, wenn nach einem Schutzbefund kein Browser-Abruf erfolgen soll." aria-label="Mehr Informationen zur automatischen Überprüfung">i</button></div><a class="back" href="/">Fallmonitor</a></div></header>
  <main>
    <section class="hero">
      <div class="kicker">URL prüfen</div>
      <form id="run-form" class="url-form">
        <input id="url" class="url-input" type="url" required maxlength="2048" placeholder="https://www.beispiel.de" aria-label="Öffentliche URL">
        <button id="run-button" class="start" type="submit"><span id="spinner" class="spinner" hidden></span><span id="start-label">Erfassung starten</span></button>
      </form>
      <div class="micro">Keine Logins, Paywalls oder CAPTCHAs <button class="info" type="button" data-info="URL bedeutet Uniform Resource Locator, also die Internetadresse. Es werden nur öffentlich erreichbare Seiten abgerufen. robots.txt und technische Schutzmaßnahmen werden respektiert." aria-label="Mehr Informationen zu den Abrufgrenzen">i</button></div>
      <div id="verification-note" class="verification-note" hidden>Automatische Überprüfung aus: Bei Seitenschutz wird kein Browser-Abruf gestartet. Öffentliche Rechtstext-Unterseiten werden weiterhin direkt geprüft.</div>
    </section>

    <details id="trace-panel" class="trace" hidden>
      <summary><span class="chevron">›</span><span>Prüfverlauf</span><button class="info" type="button" data-info="Hier werden die einzelnen Arbeitsschritte und ihre Ergebnisse fortlaufend dokumentiert." aria-label="Mehr Informationen zum Prüfverlauf">i</button><span id="run-state" class="run-state">wird vorbereitet</span></summary>
      <div id="events" class="events" role="log" aria-live="polite" aria-relevant="additions"></div>
    </details>

    <aside id="protection-warning" class="protection" role="alert" hidden>
      <strong>SEITENSCHUTZ ERKANNT</strong>
      <p id="protection-message">Die Seite kann nicht automatisiert erfasst werden. Öffentliche AGB- und Datenschutz-Unterseiten wurden ersatzweise geprüft.</p>
    </aside>

    <section id="result" class="result" hidden>
      <div id="evidence-warning" class="evidence-warning" role="alert" hidden></div>
      <div class="result-head"><h2>Beweiselemente</h2><span id="capture-status" class="capture-status"></span><button class="info" type="button" data-info="Grüne Elemente sind vorhanden. Graue Elemente waren nicht anwendbar oder konnten nicht erzeugt werden." aria-label="Mehr Informationen zu den Beweiselementen">i</button><a id="package-download" class="download" href="#">Beweispaket herunterladen</a></div>
      </section>
    </section>
  </main>
  <div id="popover" class="popover" role="dialog" hidden></div>

<script>
(() => {
  const terminal=new Set(["completed","completed_with_warnings","failed","protected","baseline_created","unchanged"]);
  const toolLabels={queued:"Vorbereitung",fetch:"Seite abrufen",browser:"Browser-Erfassung",normalize:"Inhalt aufbereiten",legal_pages:"Rechtstexte suchen",screenshot:"Ansicht festhalten",compare:"Stand einordnen",warc:"Archiv erstellen",manifest:"Prüfwerte bilden",timestamp:"Zeitpunkt belegen"};
  const help={raw_html:"HTML bedeutet Hypertext Markup Language. Das ist der unveränderte technische Quelltext der tatsächlich erfassten Seite.",response_headers:"HTTP bedeutet Hypertext Transfer Protocol. Diese Kopfdaten enthalten technische Angaben des Webservers, etwa Inhaltstyp und Abrufzeitpunkt.",normalized_text:"Bereinigter Seiteninhalt ohne typische flüchtige Bestandteile. Er dient später dem stabilen Vergleich.",legal_pages:"AGB steht für Allgemeine Geschäftsbedingungen. Hier stehen die gefundenen Rechtstext-Links sowie getrennt die für das Bild tatsächlich gewählte Klauselseite.",capture_transparency:"Dokumentiert überprüfbar, wie die Seite erfasst wurde: Browserkennung, Automatisierungserkennung, Proxy, frischer Browserzustand, robots.txt sowie angefragte und tatsächlich erfasste URL.",previous_normalized_text:"Der normalisierte Inhalt des vorherigen Abrufs.",diff:"Diff ist die Kurzform für Difference, also Unterschied. Gezeigt wird der konkrete Textunterschied zwischen zwei Seitenständen.",requested_page_screenshot:"Screenshot des sichtbaren Zustands unter der ursprünglich eingegebenen URL. Bei Seitenschutz kann dies eine Challenge- oder Anmeldeseite sein; sie wird nicht als erfolgreich erfasste Website ausgegeben.",screenshot:"Ganzseiten-Aufnahme der tatsächlich erfassten URL. Wenn Chromium auf der Hosting-Laufzeit abbricht, wird stattdessen ein deutlich beschriftetes, browserloses Beweisbild aus dem gespeicherten HTML gezeigt; das ist keine pixelgetreue Live-Aufnahme. PNG bedeutet Portable Network Graphics.",agb_screenshot:"Bild des eigentlichen AGB-Klauseltexts. Ist der zuerst gefundene AGB-Link nur eine Übersicht, wird innerhalb derselben Website eine konkrete Klauselseite ausgewählt. Navigation und Fußzeile werden in der browserlosen Ansicht ausgeblendet. Gefundene und tatsächlich abgebildete URL sowie der SHA-256-Prüfwert stehen im Beweispaket.",privacy_screenshot:"Aufnahme des ersten öffentlichen Links zur Datenschutzerklärung. Bei einem Chromium-Abbruch kann dies ein deutlich beschriftetes HTML-Beweisbild statt einer pixelgetreuen Live-Aufnahme sein. URL, Art der Aufnahme und SHA-256-Prüfwert stehen im Beweispaket.",warc:"WARC bedeutet Web ARChive. Das Archivformat speichert den abgerufenen Seiteninhalt zusammen mit technischen Abrufinformationen gemeinsam in einer Beweisdatei.",cdx:"CDX bezeichnet die Indexdatei eines Webarchivs. Sie hilft dabei, einzelne Abrufe innerhalb einer WARC-Datei gezielt wiederzufinden.",warc_status:"Dokumentiert, ob die WARC-Aufnahme vollständig war oder aus welchem Grund sie nicht erzeugt werden konnte.",manifest:"Das Manifest ist die Inhaltsliste des Beweispakets. SHA-256 bedeutet Secure Hash Algorithm mit 256 Bit. Der daraus gebildete Hash ist ein digitaler Fingerabdruck: Schon eine kleine Dateiänderung erzeugt einen anderen Prüfwert.",manifest_digest:"Der Manifest-Hash ist der digitale SHA-256-Fingerabdruck der gesamten Inhaltsliste. Er ermöglicht die spätere Integritätsprüfung des Beweispakets.",timestamp_query:"RFC 3161 ist ein technischer Standard für vertrauenswürdige Zeitstempel; RFC bedeutet Request for Comments. Diese Datei enthält die Anfrage an den Zeitstempeldienst.",timestamp_response:"Antwort der TSA auf die Zeitstempelanfrage. TSA bedeutet Time Stamping Authority, also Zeitstempelstelle. Sie ordnet den Manifest-Hash einem überprüfbaren Zeitpunkt zu.",wayback_status:"Status einer optionalen zusätzlichen Archivierung bei der Wayback Machine, einem öffentlichen Webarchiv.",report:"Lesbarer PDF-Bericht über Aufnahme, Integrität und offene menschliche Prüfung. PDF bedeutet Portable Document Format."};
  help.screenshot_interactions="Dokumentiert für jeden Screenshot, ob ein Cookie-Banner über eine eindeutig datensparsame Option geschlossen wurde. Leere Listen bedeuten, dass kein solcher Klick ausgeführt wurde.";
  help.capture_index="Pfadsicherer Index aller Originale, Ableitungen, Bildkacheln, Hashes und Vollständigkeitsangaben.";
  help.capture_metrics="Gemessene Laufzeit-, Speicher-, Request- und Größenwerte; nicht messbare Werte sind begründet.";
  help.run_result="Maschinenlesbarer Endstatus mit erfasster URL, Schutzbefund, Abbruchphase und erhaltenen Zwischenartefakten.";
  help.screenshot="Validierte Ganzseitenaufnahme oder lückenlose Originalkachelserie; die WebP-Datei dient nur als Vorschau.";
  help.protection_report="Dokumentiert die erkannte Schutzart, die blockierte Hauptseite, alle direkt geprüften Rechtstext-Unterseiten und deren Fehler. Der Bericht ist kein Beleg für Inhalte hinter dem Seitenschutz.";
  const hiddenArtifacts=new Set(["model_input","model_output","clause_model_input","clause_model_output"]);
  const primaryArtifacts=new Set(["requested_page_screenshot","screenshot","agb_screenshot","privacy_screenshot","normalized_text"]);
  const technicalOrder=["report","legal_pages","protection_report","previous_normalized_text","diff","capture_index","capture_metrics","run_result","screenshot_interactions","capture_transparency","raw_html","response_headers","warc","cdx","warc_status","manifest","manifest_digest","timestamp_query","timestamp_response","wayback_status"];
  const roleOrder=["main","requested","agb","privacy"];
  const form=document.getElementById("run-form"),input=document.getElementById("url"),start=document.getElementById("run-button"),spinner=document.getElementById("spinner"),startLabel=document.getElementById("start-label"),trace=document.getElementById("trace-panel"),events=document.getElementById("events"),result=document.getElementById("result"),pills=document.getElementById("pills"),protection=document.getElementById("protection-warning"),verificationMode=document.getElementById("verification-mode"),verificationNote=document.getElementById("verification-note");
  let currentInfo="";
  async function api(url,options){const response=await fetch(url,options);if(!response.ok){let message=`HTTP ${response.status}`;try{message=(await response.json()).detail||message}catch(_){}throw new Error(message)}return response.json()}
  function eventState(run,item,index){if(item.state==="failed")return "failed";if(String(item.state).includes("warning"))return "warning";if(index===(run.audit_log||[]).length-1&&!terminal.has(run.status))return "active";const stepState=(run.steps||{})[item.step];return stepState==="failed"?"failed":(stepState==="warning"?"warning":(stepState==="active"?"active":"done"))}
  function renderRun(run){const state=document.getElementById("run-state"),message=run.message||run.status,hasProtection=run.status==="protected"||message.includes("SEITENSCHUTZ ERKANNT");state.textContent=terminal.has(run.status)?message:`Aktiv · ${toolLabels[run.current_step]||"Prüfung läuft"}`;state.title=message;state.className="run-state "+(run.status==="completed"?"ok":(run.status.includes("warning")||run.status==="failed"||hasProtection?"warn":""));events.replaceChildren();(run.audit_log||[]).forEach((item,index)=>{const row=document.createElement("div");row.className=`event ${eventState(run,item,index)}`;const dot=document.createElement("span");dot.className="event-dot";dot.setAttribute("aria-hidden","true");const content=document.createElement("div"),top=document.createElement("div");top.className="event-top";const tool=document.createElement("b");tool.textContent=toolLabels[item.step]||item.step;const time=document.createElement("time");const date=new Date(item.timestamp);time.textContent=Number.isNaN(date.valueOf())?"":date.toLocaleTimeString("de-DE",{hour:"2-digit",minute:"2-digit",second:"2-digit"});const text=document.createElement("p");text.textContent=item.message;top.append(tool,time);content.append(top,text);row.append(dot,content);events.append(row)});events.scrollTop=events.scrollHeight;if(hasProtection){protection.hidden=false;document.getElementById("protection-message").textContent=message}}
  async function streamEvidenceRun(payload){const response=await fetch("/api/v1/evidence-runs/stream",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});if(!response.ok){let message=`HTTP ${response.status}`;try{message=(await response.json()).detail||message}catch(_){}throw new Error(message)}if(!response.body)throw new Error("Der Prüfverlauf konnte nicht geöffnet werden.");const reader=response.body.getReader(),decoder=new TextDecoder();let buffer="",completed=null;while(true){const {value,done}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});const lines=buffer.split("\n");buffer=lines.pop()||"";for(const line of lines){if(!line.trim())continue;const message=JSON.parse(line);if(message.type==="error")throw new Error(message.detail||"Prüflauf fehlgeschlagen.");if(message.run){renderRun(message.run);if(message.type==="complete")completed=message.run}}if(done)break}if(buffer.trim()){const message=JSON.parse(buffer);if(message.type==="error")throw new Error(message.detail||"Prüflauf fehlgeschlagen.");if(message.run){renderRun(message.run);completed=message.run}}return completed}
  verificationMode.addEventListener("change",()=>{verificationNote.hidden=verificationMode.checked});
  form.addEventListener("submit",async event=>{event.preventDefault();start.disabled=true;input.disabled=true;verificationMode.disabled=true;spinner.hidden=false;startLabel.textContent="Beweise werden erstellt";result.hidden=true;protection.hidden=true;events.replaceChildren();trace.hidden=false;trace.open=true;const state=document.getElementById("run-state");state.textContent="Verbindung wird aufgebaut …";state.className="run-state";try{const run=await streamEvidenceRun({url:input.value,verification_mode:verificationMode.checked});if(!run)throw new Error("Der Prüfverlauf wurde unerwartet beendet.");if(run.case_detail)renderArtifacts(run.case_detail);else if(run.result_available)await loadNewest(run.url)}catch(error){state.textContent=error.message;state.title=error.message;state.className="run-state warn"}finally{start.disabled=false;input.disabled=false;verificationMode.disabled=false;spinner.hidden=true;startLabel.textContent="Erfassung starten"}});
  async function loadNewest(expectedUrl){const list=(await api("/api/cases")).cases;const item=list.find(entry=>entry.url===expectedUrl)||list[0];if(!item)return;const data=await api(`/api/cases/${encodeURIComponent(item.case_id)}`);input.value=data.url;renderArtifacts(data)}
  let galleries={};
  function artifactMap(data){const warning=document.getElementById("evidence-warning"),unsuitable=data.evidence_suitability==="nicht_beweisgeeignet";warning.hidden=!unsuitable;warning.textContent=unsuitable?(data.evidence_suitability_notice||"NICHT BEWEISGEEIGNET: robots.txt konnte nicht verlässlich geprüft werden. Berechtigung, Nutzungsbedingungen und rechtliche Zulässigkeit sind eigenverantwortlich zu prüfen."):"";return new Map(data.artifacts.map(item=>[item.label,item]))}
  function setActive(wrap){document.querySelectorAll(".pill-wrap.active").forEach(node=>node.classList.remove("active"));wrap.classList.add("active")}
  function closePillMenus(except){document.querySelectorAll(".pill-menu").forEach(menu=>{if(menu!==except)menu.hidden=true});document.querySelectorAll(".pill[aria-expanded]").forEach(button=>{if(!except||button.nextElementSibling!==except)button.setAttribute("aria-expanded","false")})}
  function createDirectPill(title,available,onClick,infoText,status="available"){const wrap=document.createElement("span");wrap.className="pill-wrap"+(available?"":" unavailable")+(status==="warning"?" warning":"");const button=document.createElement("button");button.type="button";button.className="pill";button.disabled=!available;button.textContent=title;const info=document.createElement("button");info.type="button";info.className="info";info.textContent="i";info.dataset.info=infoText;info.setAttribute("aria-label",`Mehr Informationen zu ${title}`);if(available)button.addEventListener("click",onClick);wrap.append(button,info);pills.append(wrap);return wrap}
  function createMenuPill(title,items,infoText){const available=items.some(item=>item.available!==false);const wrap=document.createElement("span");wrap.className="pill-wrap"+(available?"":" unavailable");const button=document.createElement("button");button.type="button";button.className="pill";button.disabled=!available;button.textContent=`${title} ▾`;button.setAttribute("aria-haspopup","menu");button.setAttribute("aria-expanded","false");const menu=document.createElement("div");menu.className="pill-menu";menu.setAttribute("role","menu");menu.hidden=true;items.forEach(item=>{const child=document.createElement("button");child.type="button";child.setAttribute("role","menuitem");child.textContent=item.title;child.disabled=item.available===false;child.addEventListener("click",()=>{menu.hidden=true;button.setAttribute("aria-expanded","false");item.select(wrap)});menu.append(child)});const info=document.createElement("button");info.type="button";info.className="info";info.textContent="i";info.dataset.info=infoText;info.setAttribute("aria-label",`Mehr Informationen zu ${title}`);button.addEventListener("click",()=>{const open=menu.hidden;closePillMenus(menu);menu.hidden=!open;button.setAttribute("aria-expanded",String(open))});wrap.append(button,menu,info);pills.append(wrap);return wrap}
  function screenshotChoice(caseId,role,items){const labels={main:"screenshot",requested:"requested_page_screenshot",agb:"agb_screenshot",privacy:"privacy_screenshot"},gallery=galleries[role],item=items.get(labels[role]);if(gallery)return {title:gallery.title||role,available:true,select:wrap=>previewGallery(role,wrap,gallery.title||role)};if(item?.available)return {title:item.title,available:true,select:wrap=>preview(caseId,item,wrap)};return null}
  function renderArtifacts(data){result.hidden=false;galleries=data.capture_galleries||{};document.getElementById("capture-status").textContent=(data.capture_completeness||"").replaceAll("_"," ");document.getElementById("package-download").href=data.download_url||`/api/v1/cases/${encodeURIComponent(data.case_id)}/download`;pills.replaceChildren();const items=artifactMap(data),screenshots=roleOrder.map(role=>screenshotChoice(data.case_id,role,items)).filter(Boolean);const screenshotWrap=createMenuPill("Screenshots",screenshots,"Alle gesicherten Seitenansichten, getrennt nach Hauptseite und gefundenen Unterseiten.");const privacy=screenshotChoice(data.case_id,"privacy",items),privacyWrap=createDirectPill("Datenschutz-Screenshot",Boolean(privacy),()=>privacy.select(privacyWrap),help.privacy_screenshot,items.get("privacy_screenshot")?.status);const agb=screenshotChoice(data.case_id,"agb",items),agbWrap=createDirectPill("AGB-Screenshot",Boolean(agb),()=>agb.select(agbWrap),help.agb_screenshot,items.get("agb_screenshot")?.status);const texts=roleOrder.map(role=>{const gallery=galleries[role];if(!gallery?.normalized_text_url)return null;return {title:gallery.title||role,available:true,select:wrap=>previewRoleText(gallery,wrap)}}).filter(Boolean);if(!texts.length&&items.get("normalized_text")?.available){const item=items.get("normalized_text");texts.push({title:"Hauptseite",available:true,select:wrap=>preview(data.case_id,item,wrap)})}createMenuPill("Normalisierter Text",texts,"Bereinigter Text jeder erfassten Seite, getrennt nach Hauptseite, AGB und Datenschutz.");const technical=data.artifacts.filter(item=>item.available&&!hiddenArtifacts.has(item.label)&&!primaryArtifacts.has(item.label)).sort((a,b)=>{const ai=technicalOrder.indexOf(a.label),bi=technicalOrder.indexOf(b.label);return (ai<0?999:ai)-(bi<0?999:bi)}).map(item=>({title:item.title,available:true,select:wrap=>preview(data.case_id,item,wrap)}));createMenuPill("Technische Details",technical,"Technische Prüf- und Archivdateien für Sachverständige oder eine spätere Integritätskontrolle.");if(screenshots.length)screenshots[0].select(screenshotWrap)}
  function resetViewer(){document.getElementById("empty").hidden=true;document.getElementById("text-view").hidden=true;document.getElementById("legal-view").hidden=true;document.getElementById("image-view").hidden=true;document.getElementById("pdf-view").hidden=true;document.getElementById("gallery-controls").hidden=true}
  async function preview(caseId,item,wrap){closePillMenus();setActive(wrap);resetViewer();document.getElementById("viewer-title").textContent=item.title;const open=document.getElementById("viewer-open"),info=document.getElementById("viewer-info"),fileUrl=item.url||`/artifact/${encodeURIComponent(caseId)}/${encodeURIComponent(item.label)}`;open.href=fileUrl;open.hidden=false;currentInfo=help[item.label]||item.title;info.dataset.info=currentInfo;info.hidden=false;if(item.kind==="image"){const roles={screenshot:"main",requested_page_screenshot:"requested",agb_screenshot:"agb",privacy_screenshot:"privacy"},gallery=galleries[roles[item.label]];if(gallery){showGallery(gallery);return}const image=document.getElementById("image-view");image.src=fileUrl;image.hidden=false;return}if(item.kind==="pdf"){const pdf=document.getElementById("pdf-view");pdf.src=fileUrl;pdf.hidden=false;return}if(item.kind==="text"&&item.preview_available){const content=item.preview_content!==undefined?item.preview_content:(await api(`/api/cases/${encodeURIComponent(caseId)}/preview/${encodeURIComponent(item.label)}`)).content;if(item.label==="legal_pages"){renderLegal(JSON.parse(content));return}const pre=document.getElementById("text-view");pre.textContent=content;pre.hidden=false;return}const empty=document.getElementById("empty");empty.textContent="Für dieses Dateiformat steht eine sichere Download-Datei bereit.";empty.hidden=false}
  function previewGallery(role,wrap,title){closePillMenus();setActive(wrap);resetViewer();const gallery=galleries[role],viewerTitle=document.getElementById("viewer-title"),info=document.getElementById("viewer-info"),open=document.getElementById("viewer-open");viewerTitle.textContent=`Screenshot · ${title}`;info.dataset.info="Gesicherte Ansicht dieser Seite. Bei langen Seiten kann sie aus mehreren lückenlosen Kacheln bestehen.";info.hidden=false;open.hidden=true;showGallery(gallery)}
  async function previewRoleText(gallery,wrap){closePillMenus();setActive(wrap);resetViewer();const title=gallery.title||"Seite",open=document.getElementById("viewer-open"),info=document.getElementById("viewer-info");document.getElementById("viewer-title").textContent=`Normalisierter Text · ${title}`;open.href=gallery.normalized_text_url;open.hidden=false;info.dataset.info="Bereinigter, vergleichbarer Text dieser konkreten Seite.";info.hidden=false;const response=await fetch(gallery.normalized_text_url);if(!response.ok)throw new Error(`Text konnte nicht geladen werden (HTTP ${response.status}).`);const pre=document.getElementById("text-view");pre.textContent=await response.text();pre.hidden=false}

output.text:
    .switch-track { position:relative; width:32px; height:18px; border:1px solid #aeb7b3; border-radius:999px; background:#d9dddb; transition:.16s ease; pointer-events:none; }
    .switch-track::after { content:""; position:absolute; top:2px; left:2px; width:12px; height:12px; border-radius:50%; background:#fff; box-shadow:0 1px 3px #26332e40; transition:.16s ease; }
    .verification-switch input:checked + .switch-track { border-color:#606865; background:#737b78; }
    .verification-switch input:checked + .switch-track::after { transform:translateX(14px); }
    .verification-switch input:focus-visible + .switch-track { outline:3px solid #9bcdb9; outline-offset:2px; }
    .verification-switch input:disabled + .switch-track { opacity:.5; }
    .back { margin-left:12px; color:var(--muted); font-size:12px; text-decoration:none; }
    main { width:min(960px,calc(100% - 32px)); margin:clamp(34px,6vh,62px) auto 70px; }
    .hero { max-width:780px; }
    .kicker { color:var(--green); font-size:11px; font-weight:800; letter-spacing:.12em; text-transform:uppercase; }
    h2,p { margin:0; }
    .url-form { display:grid; grid-template-columns:minmax(0,1fr) auto; gap:8px; margin-top:10px; }
    .url-input { width:100%; height:50px; border:1px solid #cfdad5; border-radius:11px; background:#fff; color:var(--ink); padding:0 15px; box-shadow:0 1px 2px rgb(20 50 41 / .04); }
    .start { height:50px; display:inline-flex; align-items:center; justify-content:center; gap:9px; border:0; border-radius:11px; background:var(--green); color:#fff; padding:0 20px; font-weight:760; cursor:pointer; }
    .start:hover { background:var(--green-dark); }
    .start:disabled,.url-input:disabled { opacity:.55; cursor:not-allowed; }
    .spinner { width:17px; height:17px; border:2px solid #ffffff66; border-top-color:#fff; border-radius:50%; animation:spin .75s linear infinite; }
    @keyframes spin { to { transform:rotate(360deg); } }
    .micro { display:flex; align-items:center; gap:6px; margin-top:9px; color:var(--muted); font-size:11px; }
    .verification-note { margin-top:10px; border-left:3px solid #747b78; padding:6px 9px; background:#f0f1f0; color:#505754; font-size:11px; }
    .info { width:19px; height:19px; display:inline-grid; place-items:center; flex:0 0 auto; border:1px solid #b9c8c1; border-radius:50%; background:#fff; color:var(--green); padding:0; font:750 11px/1 Georgia,serif; cursor:pointer; }
    .trace { margin-top:20px; border:1px solid #d7e5dd; border-radius:12px; background:#f3f8f5; overflow:hidden; box-shadow:0 1px 2px rgb(20 50 41 / .03); }
    .trace summary { display:flex; align-items:center; gap:9px; min-height:48px; padding:0 15px; color:#3f5d51; cursor:pointer; list-style:none; font-weight:680; }
    .trace summary::-webkit-details-marker { display:none; }
    .chevron { color:var(--muted); transition:transform .18s ease; }
    .trace[open] .chevron { transform:rotate(90deg); }
    .run-state { max-width:58%; margin-left:auto; overflow:hidden; color:#6a8177; font-size:11px; font-weight:650; text-overflow:ellipsis; white-space:nowrap; }
    .run-state.ok { color:var(--green); }
    .run-state.warn { color:var(--amber); }
